'use strict';
const paths={home:'M3 10 12 3l9 7v11h-6v-7H9v7H3Z',tasks:'M5 4h14a2 2 0 0 1 2 2v10a2 2 0 0 1-2 2H9l-5 4v-4H3V6a2 2 0 0 1 2-2Z',apps:'M3 3h7v7H3ZM14 3h7v7h-7ZM3 14h7v7H3ZM14 14h7v7h-7Z',account:'M20 21v-2a7 7 0 0 0-14 0v2ZM17 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',note:'M5 3h10l4 4v14H5ZM14 3v5h5M8 12h8M8 16h6',folder:'M3 6h7l2 3h9v12H3ZM3 6V4h7l2 2',clock:'M12 8v5l3 2M4 5 2 7M20 5l2 2M20 13a8 8 0 1 1-16 0 8 8 0 0 1 16 0',search:'M20 20l-5-5M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0',back:'m14 5-7 7 7 7',arrow:'m9 5 7 7-7 7',plus:'M12 5v14M5 12h14',model:'M8 3v3M16 3v3M8 18v3M16 18v3M3 8h3M3 16h3M18 8h3M18 16h3M6 6h12v12H6Z',globe:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0M3 12h18M12 3c5 6 5 12 0 18-5-6-5-12 0-18',sun:'M12 3v2M12 19v2M3 12h2M19 12h2M5 5l2 2M17 17l2 2M5 19l2-2M17 7l2-2M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0',network:'M4 7h16v11H4ZM9 21h6M12 18v3',up:'m6 14 6-6 6 6',down:'m6 10 6 6 6-6'};
const icon=(name,cls='')=>`<svg class="${cls}" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.apps}"/></svg>`;
let s={tab:'apps',section:'overview',page:null,edit:false,dirty:false,dialog:null,query:'',filter:'all',scenario:'ready',lang:'zh',enabled:true,installed:false,busy:false,order:['note','clock','folder'],hidden:[],scroll:{overview:0,discover:0}};
let rendered=null, forceScrollTop=false;
const $=id=>document.getElementById(id),t=(zh,en)=>s.lang==='zh'?zh:en,appIcon=name=>`<span class="appicon">${icon(name)}</span>`;
const names={note:()=>t('笔记','Notes'),clock:()=>t('定时任务','Scheduled tasks'),folder:()=>t('工作区文件','Workspace files')};
const act=(action,body,cls='textbtn',attrs='')=>`<button class="${cls}" data-action="${action}" ${attrs}>${body}</button>`;
const arrow=()=>icon('arrow','chev');
function bottom(){return `<nav class="bottom" aria-label="${t('主导航','Main navigation')}">${['home','tasks','apps','account'].map((n,i)=>act('tab:'+n,icon(n)+`<span>${[t('首页','Home'),t('任务','Tasks'),t('应用','Apps'),t('我的','Account')][i]}</span>`,s.tab===n?'active':'',s.tab===n?'aria-current="page"':'')).join('')}</nav>`;}
function header(){return s.edit?`<div class="pagebar">${act('cancel',t('取消','Cancel'))}<h2>${t('整理概览','Edit overview')}</h2>${act('save',t('完成','Done'))}</div>`:`<div class="topline">${returnTo?act('back',icon('back'),'iconbtn',`aria-label="${t('返回我的插件','Back to My Plugins')}"`):''}<div class="tabs" role="tablist" aria-label="${t('应用栏目','App sections')}">${['overview','discover'].map(n=>act('section:'+n,n==='overview'?t('概览','Overview'):t('发现','Discover'),s.section===n?'selected':'',`role="tab" aria-selected="${s.section===n}"`)).join('')}</div>${s.section==='overview'?act('edit',t('整理','Edit')):''}</div>`;}
function bar(title,back='back'){return `<div class="pagebar">${act(back,icon('back'),'iconbtn',`aria-label="${t('返回','Back')}"`)}<h2>${title}</h2></div>`;}
function row(action,name,description,glyph='apps',trailing=''){return act(action,appIcon(glyph)+`<span class="words"><strong>${name}</strong><small>${description}</small></span>`+(trailing||arrow()),'row');}
function empty(title,body,action,label){return `<div class="empty">${appIcon('apps')}<h3>${title}</h3><p>${body}</p>${act(action,label,'primary')}</div>`;}
function stateView(){if(s.scenario==='loading')return `<div role="status" aria-label="${t('加载中','Loading')}">${'<div class="skeleton"></div>'.repeat(3)}</div>`;if(s.scenario==='error')return empty(t('暂时未能加载','Could not load this view'),t('你的布局和浏览位置已保留，请再试一次。','Your layout and browsing position are kept. Try again.'),'retry',t('重试','Try again'));return null;}
function overview(){let state=stateView();if(state)return state;if(s.scenario==='empty')return empty(t('把要用的应用放在这里','Make room for your apps'),t('从发现添加应用，让熟悉的工具触手可及。','Find an app to add its tools to your overview.'),'section:discover',t('去发现应用','Discover apps'));
let ids=s.order.filter(n=>s.edit||(!s.hidden.includes(n)&&(n!=='note'||s.enabled)));
return `<div class="contextline">${icon('apps')} ${t('你的应用，按你的方式排列','Your apps, arranged your way')}</div><div class="grouphead"><h3>${t('我的概览','Your overview')}</h3><small>${s.edit?t('选择显示内容','Choose what to show'):t('此设备','This device')}</small></div>${ids.map((n)=>`<article class="toolcard"><button class="cardlink" data-action="launch:${n}" aria-label="${names[n]()}" ${s.edit?'disabled':''}></button><div class="toolhead">${appIcon(n)}<div><strong>${names[n]()}</strong><small>${n==='folder'?(s.scenario==='offline'?t('电脑离线','Desktop offline'):t('已连接的电脑','Connected desktop')):t('本机可用','On this device')}</small></div>${arrow()}</div><div class="widget-body">${(n==='note'||n==='siyuan')?`<b>${t('发布前的检查清单','Before the next release')}</b>${t('继续整理你的想法与记录','Pick up your thoughts and notes')}`:n==='clock'?`<b>${t('周一回顾项目进展','Review project progress')}</b>${t('下次执行 · 周一 09:00','Next run · Mon, 09:00')}`:`<b>${t('Workspace · 项目资料','Workspace · Project files')}</b>${s.scenario==='offline'?t('连接恢复后可继续浏览，本机应用仍可使用','Browse again when connected. Local apps remain available.'):t('浏览电脑中的文件与目录','Browse files and folders on your desktop')}`}</div>${s.edit?`<div class="edittools">${act('move:'+n,icon('up'),'iconbtn',`aria-label="${t('上移','Move up')} ${names[n]()}"`)}${act('lower:'+n,icon('down'),'iconbtn',`aria-label="${t('下移','Move down')} ${names[n]()}"`)}${act('hide:'+n,s.hidden.includes(n)?t('显示','Show'):t('隐藏','Hide'))}</div>`:''}</article>`).join('')}${!s.edit?act('section:discover',icon('plus')+t('从发现添加','Find more apps'),'addlink'):''}`;}
function search(){return `<label class="search">${icon('search')}<input id="search" aria-label="${t('搜索应用','Search apps')}" placeholder="${t('搜索应用','Search apps')}" value="${s.query.replaceAll('&','&amp;').replaceAll('"','&quot;').replaceAll('<','&lt;')}"></label>`;}
function discover(){let state=stateView();if(state)return search()+state;if(s.scenario==='empty')return search()+empty(t('没有找到应用','No apps found'),t('换个关键词，或稍后再回来看看。','Try another search, or come back later.'),'retry',t('清除搜索','Clear search'));
const entries=[['note',t('笔记','Notes'),t('记录、编辑，带进下一段对话','Write, edit and bring notes into a conversation')],['siyuan',t('思源笔记','SiYuan'),t('连接你的知识与笔记','Connect your knowledge and notes')],['clock',t('定时任务','Scheduled tasks'),t('让重复的工作按时开始','Give recurring work a schedule')]].filter(x=>!s.query||`${x[1]} ${x[2]}`.toLowerCase().includes(s.query.toLowerCase()));
return search()+(!s.query?`<button class="feature" data-action="detail:siyuan"><span>${t('应用精选','APP SPOTLIGHT')}</span><h2>${t('让散落的想法，<br>有一个归处。','A place for<br>your scattered ideas.')}</h2><div class="feature-foot">${icon('note')} ${t('认识思源笔记','Meet SiYuan')} ${icon('arrow')}</div></button>`:'')+`<div class="grouphead"><h3>${s.query?t('搜索结果','Search results'):t('发现更多','More to explore')}</h3><small>${t('适用于此设备','For this device')}</small></div>`+(entries.length?entries.map(([id,name,desc])=>row('detail:'+id,name,desc,id==='siyuan'?'note':id,`<span class="pill">${id==='siyuan'&&!s.installed?t('获取','Get'):t('打开','Open')}</span>`)).join(''):empty(t('没有找到应用','No apps found'),t('试试其他关键词。','Try another search.'),'retry',t('清除搜索','Clear search')));}
function account(){return `<h1 class="accounttitle">${t('我的','Account')}</h1><div class="accounthead"><span class="avatar">M</span><div><strong>${t('Muse 用户','Muse user')}</strong><small>${t('账号设置','Account settings')}</small></div>${arrow()}</div><div class="grouphead"><h3>${t('应用与服务','Apps & services')}</h3></div><div class="settings">${row('plugins',t('我的插件','My Plugins'),t('安装、更新与使用状态','Installations, updates and status'),'apps')}${row('model',t('模型管理','Models'),t('本地语音与模型设置','Local speech and model settings'),'model')}${row('provider',t('商店来源','Store provider'),t('管理应用目录来源','Manage catalog sources'),'globe')}</div><div class="grouphead"><h3>${t('偏好设置','Preferences')}</h3></div><div class="settings">${row('theme',t('外观','Appearance'),t('跟随系统或自行选择','Follow system or choose a theme'),'sun')}${row('language',t('语言','Language'),s.lang==='zh'?'简体中文':'English','globe')}</div><div class="grouphead"><h3>${t('关于 OpenMuse','About OpenMuse')}</h3></div><p class="version">${t('版本','Version')} 1.0.0 (9)</p>`;}
function plugins(){let items=[['note',names.note(),s.enabled?t('已启用 · 本机','Enabled · This device'):t('已停用 · 本机','Disabled · This device')],['clock',names.clock(),t('内置 · 本机','Built-in · This device')]];if(s.installed)items.push(['siyuan',t('思源笔记','SiYuan'),t('已启用 · 本机','Enabled · This device')]);if(s.filter==='disabled')items=items.filter(x=>x[0]==='note'&&!s.enabled);if(s.filter==='updates')items=[];
return `<p class="subtext">${t('此设备上的插件；其他设备的安装状态独立管理。','Plugins on this device. Other devices are managed separately.')}</p><div class="filters" style="margin-top:22px">${['all','updates','disabled'].map((f,i)=>act('filter:'+f,[t('全部','All'),t('更新','Updates'),t('已停用','Disabled')][i],s.filter===f?'selected':'')).join('')}</div>${items.length?items.map(([id,name,desc])=>row('manage:'+id,name,desc,id==='siyuan'?'note':id)).join(''):empty(t('这里暂时没有插件','Nothing here yet'),s.filter==='updates'?t('当前没有已确认的可用更新。','No verified updates are available.'):t('没有符合当前筛选的插件。','No plugins match this filter.'),'filter:all',t('查看全部','Show all'))}${act('from-manage',t('发现更多应用','Discover more apps'),'addlink')}`;}
function detail(id,manage=false){const n=id==='siyuan'?t('思源笔记','SiYuan'):names[id]();const installed=id!=='siyuan'||s.installed;
return `<div class="detailhero">${appIcon(id==='siyuan'?'note':id)}<div><h2>${n}</h2><p>${t('适用于 iOS 与 Android','For iOS and Android')}</p></div></div><p class="badge" style="margin-top:22px">${installed?t('已安装在此设备','Installed on this device'):t('可添加到此设备','Available for this device')}</p>${act(installed?'launch:'+id:'install',s.busy?t('正在安装…','Installing…'):installed?t('打开应用','Open app'):t('获取应用','Get app'),'primary wide',s.busy?'disabled':'')}${s.installed&&id==='siyuan'?act('show-overview',t('在概览中查看','View in overview'),'secondary wide'):''}<div class="detailcopy"><h3>${t('关于这个应用','About this app')}</h3><p>${id==='clock'?t('查看并管理重复执行的任务。每个任务保留自己的设备与工作区。','View recurring tasks, each with its own device and workspace.'):t('记录与整理内容，并通过统一资源引用，把内容带入任务。','Write and organize content, then bring it into tasks using resource references.')}</p><h3>${t('数据与权限','Data & permissions')}</h3><p>${t('由你选择要打开的内容。连接远程设备或服务时，另行确认相应授权。','Choose the content you open. Remote connections request their own authorization.')}</p></div>${manage&&id==='note'?act('toggle-plugin',s.enabled?t('停用插件','Disable plugin'):t('启用插件','Enable plugin'),'secondary wide'):''}${manage&&id==='siyuan'?act('uninstall',t('卸载插件','Uninstall plugin'),'textbtn wide'):''}`;}
function render(){const content=$('screen').querySelector('.content');if(content&&rendered?.tab==='apps'&&!rendered.page&&!rendered.edit&&!forceScrollTop)s.scroll[rendered.section]=content.scrollTop;forceScrollTop=false;let inner='',top='',isRoot=!s.page;
if(s.page){const [kind,id]=s.page.split(':');top=bar(kind==='plugins'?t('我的插件','My Plugins'):kind==='manage'?t('插件管理','Manage plugin'):t('应用详情','App details'));inner=kind==='plugins'?plugins():detail(id,kind==='manage');}
else if(s.tab==='apps'){top=header();inner=s.section==='overview'?overview():discover();}
else if(s.tab==='account')inner=account();
else inner=`<h1 class="simple-title">${s.tab==='home'?t('首页','Home'):t('任务','Tasks')}</h1><p class="subtext">${t('此处保留现有页面，仅演示四 Tab 导航。','Existing page retained. This preview demonstrates navigation only.')}</p><div class="placeholder-row">${s.tab==='home'?t('最近打开的资源','Recently opened resources'):t('继续你的对话','Continue your conversation')}<small>${t('现有功能不因合并应用中心而重置','Existing work remains when you switch tabs')}</small></div>`;
$('phone').classList.toggle('dark',$('theme').value==='dark');$('screen').innerHTML=top+`<div class="content ${s.edit?'editing':''}">${inner}</div>`+(isRoot?bottom():'')+(s.dialog?dialog(): '');
if(!s.page&&!s.edit&&s.tab==='apps')$('screen').querySelector('.content').scrollTop=s.scroll[s.section]||0;
rendered={tab:s.tab,page:s.page,section:s.section,edit:s.edit};
const sections={overview:[t('先使用，再探索。','Use first. Explore next.'),t('概览复用插件组件与个人布局。右侧整理不与标题竞争空间。','Overview retains plugin widgets and personal layout. Editing has its own action bar.')],discover:[t('发现，是另一个栏目。','Discover is a peer section.'),t('没有第二套底栏或 My Plugins 顶栏。搜索与详情沿用发现的内容结构。','One bottom bar. No My Plugins section. Search and detail retain the discovery structure.')],account:[t('管理，回到我的。','Management lives in Account.'),t('My Plugins 与模型管理、商店来源分组呈现；管理页独立返回，运行与安装各有归属。','My Plugins sits alongside models and catalog sources, with a separate return path.')]};const note=sections[s.tab==='account'||s.page?.startsWith('manage')||s.page==='plugins'?'account':s.section]||sections.overview;$('note-title').textContent=note[0];$('note-copy').textContent=note[1];}
function dialog(){return `<div class="overlay" role="dialog" aria-modal="true" aria-label="${t('确认操作','Confirm action')}"><div class="sheet"><h2>${s.dialog==='edit'?t('保存布局更改？','Save layout changes?'):s.dialog==='uninstall'?t('卸载思源笔记？','Uninstall SiYuan?'):t('应用预览','App preview')}</h2><p>${s.dialog==='edit'?t('选择保存或放弃，你也可以继续整理。','Save or discard your changes, or keep editing.'):s.dialog==='uninstall'?t('移除此设备上的应用入口。你的文档和账号不会因此被删除。','Remove the app entry on this device. Your documents and account are not deleted.'):t('正式应用将打开对应插件。本原型只用于审核导航与页面交互。','The shipped app will open the plugin. This prototype previews navigation and interaction only.')}</p>${s.dialog==='edit'?act('confirm-save',t('保存更改','Save changes'),'primary')+act('confirm-discard',t('放弃更改','Discard changes'),'secondary')+act('close-dialog',t('继续整理','Keep editing')):s.dialog==='uninstall'?act('confirm-uninstall',t('确认卸载','Uninstall'),'primary')+act('close-dialog',t('取消','Cancel')):act('close-dialog',t('返回','Back'),'primary')}</div></div>`;}
let toastTimer;function toast(message){$('toast').textContent=message;$('toast').classList.add('shown');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('shown'),2400);}
let pending=null,before=null,returnTo=null;
function navigate(fn){if(s.edit&&s.dirty){pending=fn;s.dialog='edit';render();return;}if(s.edit){s.edit=false;}fn();render();}
function run(action){const [verb,id]=action.split(':');if(verb==='tab'){navigate(()=>{s.page=null;returnTo=null;if(id==='apps'&&s.tab==='apps'){s.section='overview';s.scroll.overview=0;forceScrollTop=true;}s.tab=id;});return;}
if(verb==='section'){navigate(()=>{s.page=null;s.tab='apps';s.section=id;});return;}
if(verb==='edit'){before={order:[...s.order],hidden:[...s.hidden]};s.edit=true;s.dirty=false;render();return;}
if(verb==='lower'){const i=s.order.indexOf(id);if(i<s.order.length-1)[s.order[i],s.order[i+1]]=[s.order[i+1],s.order[i]];s.dirty=true;render();return;}
if(verb==='move'){const i=s.order.indexOf(id);if(i>0)[s.order[i-1],s.order[i]]=[s.order[i],s.order[i-1]];s.dirty=true;render();return;}
if(verb==='hide'){s.hidden=s.hidden.includes(id)?s.hidden.filter(x=>x!==id):[...s.hidden,id];s.dirty=true;render();return;}
if(verb==='save'){s.edit=false;s.dirty=false;render();toast(t('布局已保存（演示）','Layout saved (demo)'));return;}
if(verb==='cancel'){if(s.dirty){pending=()=>{};s.dialog='edit';render();}else{s.edit=false;render();}return;}
if(verb==='confirm-save'||verb==='confirm-discard'){if(verb==='confirm-discard'&&before){s.order=before.order;s.hidden=before.hidden;}s.edit=false;s.dirty=false;s.dialog=null;pending?.();pending=null;render();return;}
if(verb==='close-dialog'){s.dialog=null;pending=null;render();return;}
if(verb==='detail'||verb==='manage'){s.page=verb+':'+id;render();return;}
if(verb==='plugins'){s.page='plugins';s.tab='account';render();return;}
if(verb==='filter'){s.filter=id;render();return;}
if(verb==='from-manage'){returnTo='plugins';s.page=null;s.tab='apps';s.section='discover';render();toast(t('使用返回可回到插件管理','Back returns to plugin management'));return;}
if(verb==='back'){if(s.page?.startsWith('manage'))s.page='plugins';else if(s.page==='plugins')s.page=null;else if(s.page)s.page=null;else if(returnTo){s.page=returnTo;s.tab='account';returnTo=null;}render();return;}
if(verb==='install'){s.busy=true;render();setTimeout(()=>{s.busy=false;s.installed=true;if(!s.order.includes('siyuan')){s.order.push('siyuan');names.siyuan=()=>t('思源笔记','SiYuan');}render();toast(t('已添加到概览（演示）','Added to overview (demo)'));},950);return;}
if(verb==='show-overview'){s.page=null;s.tab='apps';s.section='overview';s.scenario='ready';$('state').value='ready';render();return;}
if(verb==='toggle-plugin'){s.enabled=!s.enabled;render();toast(s.enabled?t('概览入口已恢复','Overview entry restored'):t('入口已停用，布局与数据保留','Entry disabled. Layout and data kept.'));return;}
if(verb==='uninstall'){s.dialog='uninstall';render();return;}
if(verb==='confirm-uninstall'){s.installed=false;s.order=s.order.filter(x=>x!=='siyuan');s.dialog=null;s.page='plugins';render();return;}
if(verb==='retry'){s.scenario='ready';s.query='';$('state').value='ready';render();return;}
if(verb==='launch'){if(id==='folder'&&s.scenario==='offline'){toast(t('电脑离线，请连接后重试','Desktop is offline. Connect and try again.'));return;}s.dialog='launch';render();return;}
if(verb==='theme'){$('theme').value=$('theme').value==='light'?'dark':'light';render();return;}
if(verb==='language'){$('language').value=s.lang==='zh'?'en':'zh';s.lang=$('language').value;render();return;}
toast(t('此设置沿用现有页面，本稿仅调整入口','This setting retains its existing page.'));}
$('screen').addEventListener('click',e=>{const b=e.target.closest('button[data-action]');if(b&&!b.disabled)run(b.dataset.action);});
$('screen').addEventListener('input',e=>{if(e.target.id!=='search')return;const start=e.target.selectionStart;s.query=e.target.value;render();$('search').focus();$('search').setSelectionRange(start,start);});
$('language').onchange=()=>{s.lang=$('language').value;render();};$('theme').onchange=render;$('state').onchange=()=>{s.scenario=$('state').value;render();};
document.querySelector('.scenes').addEventListener('click',e=>{const b=e.target.closest('[data-scene]');if(!b)return;s.page=null;s.dialog=null;s.edit=false;s.dirty=false;s.scenario='ready';$('state').value='ready';const scene=b.dataset.scene;if(scene==='account'||scene==='plugins'){s.tab='account';if(scene==='plugins')s.page='plugins';}else{s.tab='apps';s.section=scene==='discover'?'discover':'overview';if(scene==='edit'){before={order:[...s.order],hidden:[...s.hidden]};s.edit=true;}}render();});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(s.dialog)run('close-dialog');else if(s.edit)run('cancel');else if(s.page||returnTo)run('back');}});
render();
